// Bare native addon binding the Wavelength gomobile daemon directly.
//
// This calls Wavewalletdk.xcframework's plain C functions (generated by
// `gobind -lang=objc`) straight from Bare's js.h API -- no WebAssembly, no
// JIT. Facade methods that take/return JSON share one call shape
// (NSData in, NSData out, NSError** for failure), handled by
// wavelength_call_json; the few that don't (start/stop/scalar getters/
// isRunning) are bound individually below.
//
// Streaming (MobileSubscribe/.next:) is intentionally not implemented yet --
// it needs a background-thread poll loop bridged back into JS via a
// threadsafe function, which is a separate, larger piece of work.

#include <assert.h>
#include <bare.h>
#include <js.h>
#include <stdlib.h>

#import <Foundation/Foundation.h>
#import <Wavewalletdk.h>

static NSString *
wavelength_read_string_arg(js_env_t *env, js_value_t *value) {
  int err;

  size_t len;
  err = js_get_value_string_utf8(env, value, NULL, 0, &len);
  assert(err == 0);

  char *buf = (char *) malloc(len + 1);

  err = js_get_value_string_utf8(env, value, (utf8_t *) buf, len + 1, NULL);
  assert(err == 0);

  return [[NSString alloc] initWithBytesNoCopy:buf
                                         length:len
                                       encoding:NSUTF8StringEncoding
                                   freeWhenDone:YES];
}

static NSData *
wavelength_read_data_arg(js_env_t *env, js_value_t *value) {
  NSString *str = wavelength_read_string_arg(env, value);
  return [str dataUsingEncoding:NSUTF8StringEncoding];
}

static js_value_t *
wavelength_data_to_js(js_env_t *env, NSData *data) {
  int err;
  js_value_t *result;

  if (data == nil) {
    err = js_get_null(env, &result);
    assert(err == 0);
    return result;
  }

  err = js_create_string_utf8(env, (const utf8_t *) data.bytes, data.length, &result);
  assert(err == 0);
  return result;
}

static js_value_t *
wavelength_throw(js_env_t *env, NSError *error) {
  const char *message = error.localizedDescription.UTF8String;
  js_throw_error(env, NULL, message ? message : "wavelength_error");
  return NULL;
}

typedef NSData *_Nullable (*wavelength_json_fn_t)(NSData *_Nullable reqJSON, NSError *_Nullable *_Nullable error);

static js_value_t *
wavelength_call_json(js_env_t *env, js_callback_info_t *info, wavelength_json_fn_t fn) {
  int err;

  size_t argc = 1;
  js_value_t *argv[1];

  err = js_get_callback_info(env, info, &argc, argv, NULL, NULL);
  assert(err == 0);

  NSData *req = argc >= 1 ? wavelength_read_data_arg(env, argv[0]) : nil;

  NSError *error = nil;
  NSData *result = fn(req, &error);

  if (error != nil) return wavelength_throw(env, error);

  return wavelength_data_to_js(env, result);
}

#define WAVELENGTH_JSON_METHOD(name, mobile_fn) \
  static js_value_t * \
  wavelength_##name(js_env_t *env, js_callback_info_t *info) { \
    return wavelength_call_json(env, info, mobile_fn); \
  }

WAVELENGTH_JSON_METHOD(startExternalSeedWallet, MobileStartExternalSeedWallet)
WAVELENGTH_JSON_METHOD(createWallet, MobileCreateWallet)
WAVELENGTH_JSON_METHOD(unlockWallet, MobileUnlockWallet)
WAVELENGTH_JSON_METHOD(openWalletFromPasskey, MobileOpenWalletFromPasskey)
WAVELENGTH_JSON_METHOD(deposit, MobileDeposit)
WAVELENGTH_JSON_METHOD(receive, MobileReceive)
WAVELENGTH_JSON_METHOD(prepareSend, MobilePrepareSend)
WAVELENGTH_JSON_METHOD(sendPrepared, MobileSendPrepared)
WAVELENGTH_JSON_METHOD(list, MobileList)
WAVELENGTH_JSON_METHOD(exit, MobileExit)
WAVELENGTH_JSON_METHOD(exitStatus, MobileExitStatus)
WAVELENGTH_JSON_METHOD(exitSummary, MobileExitSummary)
WAVELENGTH_JSON_METHOD(getExitPlan, MobileGetExitPlan)
WAVELENGTH_JSON_METHOD(sweepWallet, MobileSweepWallet)

#undef WAVELENGTH_JSON_METHOD

static js_value_t *
wavelength_start(js_env_t *env, js_callback_info_t *info) {
  int err;

  size_t argc = 1;
  js_value_t *argv[1];

  err = js_get_callback_info(env, info, &argc, argv, NULL, NULL);
  assert(err == 0);
  assert(argc == 1);

  NSString *cfg = wavelength_read_string_arg(env, argv[0]);

  NSError *error = nil;
  BOOL ok = MobileStart(cfg, &error);

  if (error != nil) return wavelength_throw(env, error);

  js_value_t *result;
  err = js_get_boolean(env, ok, &result);
  assert(err == 0);
  return result;
}

static js_value_t *
wavelength_stop(js_env_t *env, js_callback_info_t *info) {
  int err;

  NSError *error = nil;
  BOOL ok = MobileStop(&error);

  if (error != nil) return wavelength_throw(env, error);

  js_value_t *result;
  err = js_get_boolean(env, ok, &result);
  assert(err == 0);
  return result;
}

typedef NSData *_Nullable (*wavelength_getter_fn_t)(NSError *_Nullable *_Nullable error);

static js_value_t *
wavelength_call_getter(js_env_t *env, js_callback_info_t *info, wavelength_getter_fn_t fn) {
  NSError *error = nil;
  NSData *result = fn(&error);

  if (error != nil) return wavelength_throw(env, error);

  return wavelength_data_to_js(env, result);
}

#define WAVELENGTH_GETTER_METHOD(name, mobile_fn) \
  static js_value_t * \
  wavelength_##name(js_env_t *env, js_callback_info_t *info) { \
    return wavelength_call_getter(env, info, mobile_fn); \
  }

WAVELENGTH_GETTER_METHOD(getInfo, MobileGetInfo)
WAVELENGTH_GETTER_METHOD(status, MobileStatus)
WAVELENGTH_GETTER_METHOD(balance, MobileBalance)

#undef WAVELENGTH_GETTER_METHOD

static js_value_t *
wavelength_confirmedBalanceSat(js_env_t *env, js_callback_info_t *info) {
  int err;

  int64_t value = 0;
  NSError *error = nil;
  MobileConfirmedBalanceSat(&value, &error);

  if (error != nil) return wavelength_throw(env, error);

  char buf[32];
  snprintf(buf, sizeof(buf), "%lld", (long long) value);

  js_value_t *result;
  err = js_create_string_utf8(env, (const utf8_t *) buf, strlen(buf), &result);
  assert(err == 0);
  return result;
}

static js_value_t *
wavelength_pendingInboundSat(js_env_t *env, js_callback_info_t *info) {
  int err;

  int64_t value = 0;
  NSError *error = nil;
  MobilePendingInboundSat(&value, &error);

  if (error != nil) return wavelength_throw(env, error);

  char buf[32];
  snprintf(buf, sizeof(buf), "%lld", (long long) value);

  js_value_t *result;
  err = js_create_string_utf8(env, (const utf8_t *) buf, strlen(buf), &result);
  assert(err == 0);
  return result;
}

static js_value_t *
wavelength_walletReady(js_env_t *env, js_callback_info_t *info) {
  int err;

  BOOL value = NO;
  NSError *error = nil;
  MobileWalletReady(&value, &error);

  if (error != nil) return wavelength_throw(env, error);

  js_value_t *result;
  err = js_get_boolean(env, value, &result);
  assert(err == 0);
  return result;
}

static js_value_t *
wavelength_isRunning(js_env_t *env, js_callback_info_t *info) {
  int err;

  BOOL value = MobileIsRunning();

  js_value_t *result;
  err = js_get_boolean(env, value, &result);
  assert(err == 0);
  return result;
}

static js_value_t *
wavelength_exports(js_env_t *env, js_value_t *exports) {
  int err;

#define V(name) \
  { \
    js_value_t *val; \
    err = js_create_function(env, #name, -1, wavelength_##name, NULL, &val); \
    assert(err == 0); \
    err = js_set_named_property(env, exports, #name, val); \
    assert(err == 0); \
  }

  V(start)
  V(startExternalSeedWallet)
  V(stop)
  V(getInfo)
  V(status)
  V(balance)
  V(createWallet)
  V(unlockWallet)
  V(openWalletFromPasskey)
  V(deposit)
  V(receive)
  V(prepareSend)
  V(sendPrepared)
  V(list)
  V(exit)
  V(exitStatus)
  V(exitSummary)
  V(getExitPlan)
  V(sweepWallet)
  V(confirmedBalanceSat)
  V(pendingInboundSat)
  V(walletReady)
  V(isRunning)
#undef V

  return exports;
}

BARE_MODULE(wavelength_bare_addon, wavelength_exports)
